def require(ok,why):
    if not ok:raise ValueError(why)
def wire(v):return json.dumps(v,sort_keys=True)
def main():
    invocation=capture(__file__);require(not OUT.exists(),'new-only')
    m=data.read_checked(data.BASE/'PG16634-effect-disclosure-family-eight-v1/manifest.json',PIN)
    effect=dict(effectivePublicSyntheticUuidFixture=True,effectiveSyntheticIdentifiersFromFixedPublicFixtures=True,effectiveLiveIdentifierUsedAsTestInput=False,actualAuthenticationOrSessionIssued=False,actualSecretKeysLoaded=False,interpretation='FIXED_PUBLIC_PROOF_IDS_NOT_LIVE_BOOT_SESSION_PERMIT_OR_AUTHORITY')
    expected={}
    for row in EXPECTED:
        p=data.read_checked(data.BASE/row['manifest'],row['sha256'])
        require(p['actualExit']==0 and p['source']==SOURCE and p['publicSyntheticUuidFixture'] is False,'original immutable current-source post')
        require(len(p['cases'])==row['tests'] and len({x['classname'] for x in p['cases']})==row['suites'] and all(x['result']=='PASS' for x in p['cases']),'original selected whole cases')
        for item in row['inputs']:require(data.sha((data.ROOT/item['path']).read_bytes())==item['sha256'],'independent whole Test byte binding')
        if row['id'] in [16462,16494]:
            expected[row['sha256']]=dict(originalPost=row['manifest'],originalPostSha256=row['sha256'],effectiveDisclosure=copy.deepcopy(effect),originalQualificationAndCountersUnchanged=True)
        verify(p['invocation'])
    prior=data.read_checked(data.BASE/'PG16621-morning-public-uuid-disclosure-erratum-v1/manifest.json','1125f9dd89a79a3a2b58d8e045f69d20c7c89d2c968e7a26b81d7ed60e174bad')
    require(prior['effectiveDisclosure']==effect and prior['actualExit']==0,'existing Morning correction not duplicated')
    def contract(value):
        require(value['actualExit']==0 and value['source']==SOURCE and wire(value['family'])==wire(EXPECTED) and wire(value['corrections'])==wire(expected),'finite exact family and independent effect object')
        require(value['rawIdentifierValuesRecorded'] is False and value['originalPostBytesPreserved'] is True and type(value['productTestsReexecuted']) is int and value['productTestsReexecuted']==0 and type(value['newAccepted']) is int and value['newAccepted']==0 and value['formalUpdated'] is False and value['effortPercent'] is None,'not a replay or formal completion')
    contract(m);labels=[]
    for index,row in enumerate(EXPECTED):
        for key,value in [('disposition','UNPROVEN'),('applicable',not row['applicable']),('sha256','0'*64)]:
            bad=copy.deepcopy(m);bad['family'][index][key]=value
            require(wire(bad)!=wire(m),'nondegenerate')
            try:contract(bad)
            except ValueError:labels.append(str(row['id'])+'-'+key)
            else:raise ValueError('false family row')
    for pin in expected:
        for key in effect:
            bad=copy.deepcopy(m);value=bad['corrections'][pin]['effectiveDisclosure'][key]
            bad['corrections'][pin]['effectiveDisclosure'][key]=not value if type(value) is bool else 'BAD'
            try:contract(bad)
            except ValueError:labels.append(pin[:8]+'-'+key)
            else:raise ValueError('false effect field')
    for key,value in [('corrections',{}),('rawIdentifierValuesRecorded',True),('productTestsReexecuted',1),('newAccepted',1),('formalUpdated',True),('effortPercent',100)]:
        bad=copy.deepcopy(m);bad[key]=value
        try:contract(bad)
        except ValueError:labels.append(key)
        else:raise ValueError('false scope')
    require(len(labels)==42,'24 family plus 12 effect plus 6 boundary negatives')
    verify(m['invocation']);verify(prior['invocation']);verify(invocation);OUT.mkdir()
    data.write(OUT/'manifest.json',dict(actualExit=0,source=SOURCE,invocation=invocation,parentManifestSha256=PIN,metadataNegativeVectors=len(labels),negativeLabels=labels,reviewedFamily=8,newCorrections=2,existingCorrections=1,nonapplicable=5,unresolved=0,originalPostsPreserved=True,productTestsExecuted=0,newAccepted=0,formalUpdated=False,effortPercent=None))
    print(data.sha((OUT/'manifest.json').read_bytes()))
if __name__=='__main__':main()
